contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We accept two parameters: recipient address and an initial deposit amount to fund the contract.
    // The test will fund this test contract, then forward funds to c so rewards can be withdrawn.
    function run(address payable recipient, uint deposit) public {
        require(address(this).balance >= deposit);
        // fund contract C so it can pay out rewards
        (bool ok,) = address(c).call{value: deposit}("");
        require(ok);

        // Ensure recipient hasn't claimed bonus yet by attempting to call getFirstWithdrawalBonus
        // This will credit 100 to rewardsForA[recipient] and then call withdrawReward(recipient)
        c.getFirstWithdrawalBonus(recipient);

        // Observables: contract C balance and recipient balance
        uint cBal = address(c).balance;
        uint rBal = recipient.balance;

        // After successful getFirstWithdrawalBonus on the original, recipient should have gained 100 wei
        // and the contract balance should have decreased by 100.
        // We assert that recipient balance increased by exactly 100 relative to (deposit - c balance change).
        // Equivalently: initial c balance before bonus was deposit, after should be deposit - 100, so
        // deposit - cBal == 100  (i.e., contract lost exactly 100)
        assert(deposit - cBal == 100);
    }

    // allow contract to receive ETH to set up deposits
    receive() external payable {}
}

