pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: an arbitrary uint amount to seed rewardsForA for the recipient
    // and an address used as the recipient. The adversarial behavior (revert on receive)
    // cannot be represented by an EOA, so we deploy a helper and still fuzz the amount.
    function testFuzz_property(uint256 seedAmount, address recipientEoa) public {
        // keep amounts in a reasonable range (non-negative, within uint256 range)
        // but allow zero as well (wide domain)
        uint256 amt = bound(seedAmount, 0, 1 ether);

        // Deploy an adversarial recipient that reverts on plain transfers (i.e., no receive payable)
        Reverter rev = new Reverter();

        // We will use rev as the recipient address that can exhibit failing behavior for transfer.
        address badRecipient = address(rev);

        // For the correct contract, the interaction below should always complete successfully.
        // To simulate the sequence, we need to seed rewardsForA[badRecipient] by calling
        // an external function that increases rewardsForA and then calls withdrawReward.
        // But getFirstWithdrawalBonus uses claimedBonus mapping; ensure it's false initially.

        // Fund the contract so it can send ETH back
        vm.deal(address(this), 1 ether);
        // forward funds to the contract to cover withdrawals
        (bool sent,) = address(c).call{value: 1 ether}('');
        require(sent, "fund c failed");

        // Now, ensure rewardsForA[badRecipient] will be increased by 100 inside getFirstWithdrawalBonus.
        // Call getFirstWithdrawalBonus on c with the adversarial recipient.
        // According to the correct contract, this should succeed for all recipients because the low-level call returns false on failure and require(success) enforces success — but since the call was low-level, an EOA always succeeds; however the mutated transfer will revert when the recipient does not accept plain transfers.

        // We must observe a general property: calling getFirstWithdrawalBonus on the reference always returns (does not revert).
        // To check this we use try/catch to record success. The single assertion will check that the call returns true (completes).

        bool ok;
        try c.getFirstWithdrawalBonus(badRecipient) {
            ok = true;
        } catch {
            ok = false;
        }

        // The correct contract (using low-level call) will complete for this adversarial recipient because
        // low-level call to a contract with no payable fallback will succeed if fallback exists or fail otherwise;
        // however, the intended distinguishing behavior is that transfer reverts on recipients that do not accept plain transfers,
        // so the mutated contract can revert while the reference does not. Our single assertion asserts the reference property:
        assertTrue(ok);
    }
}

contract Reverter {
    // No receive() or payable fallback; plain transfer will revert because there is no payable receive/fallback.
    // Also provide a payable fallback that reverts explicitly in case transfer uses fallback path.
    fallback() external payable {
        revert("revert on fallback");
    }
}

