pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attacker attacker;

    function setUp() public { c = new C(); }

    // fuzzed: attacker initial funding amount and bonus amount deposited into rewardsForA
    function testFuzz_property(uint256 bonusAmount, uint256 attackerFund) public {
        // keep values in reasonable ranges but wide
        bonusAmount = bound(bonusAmount, 1, 1 ether);
        attackerFund = bound(attackerFund, 1, 1 ether);

        // deploy attacker that will reenter withdrawReward when receiving ether
        attacker = new Attacker(address(c));

        // fund attacker externally so it can receive and send txs
        vm.deal(address(attacker), attackerFund);

        // set up rewardsForA for attacker by directly calling into contract's public functions
        // The contract C in the repo exposes a mechanism getFirstWithdrawalBonus which will credit rewardsForA
        // We call getFirstWithdrawalBonus(attacker) which internally calls withdrawReward(attacker)
        // But to ensure rewardsForA[attacker] is set to bonusAmount, we simulate by first directly manipulating
        // by calling getFirstWithdrawalBonus on attacker address and then topping up rewardsForA by calling
        // withdrawReward flow won't allow arbitrary set, so instead we use a different approach: assume C has
        // rewardsForA mapping manipulable via getFirstWithdrawalBonus semantics: getFirstWithdrawalBonus adds 100
        // To keep test general and not rely on specific numeric, we will instead emulate deposit by making
        // the attacker contract hold payable fallback that accepts value and then we directly send Ether to c
        // and rely on withdrawReward to read rewardsForA. However, since rewardsForA is private and there is no
        // public setter in general, we instead use the following universal approach for this mutant difference:
        // The difference is observable when the recipient is a contract that re-enters during the external call.
        // We'll cause the reference property to be: after withdrawReward(attacker) returns, rewardsForA[attacker] == 0
        // We arrange rewardsForA[attacker] by calling a helper function on c that in the reference increases rewards
        // The provided reference has getFirstWithdrawalBonus which increases rewardsForA by 100 then calls withdrawReward.
        // So to create a situation where rewardsForA is nonzero before withdrawReward, we rely on getFirstWithdrawalBonus.

        // Ensure attacker has code that will reenter when receiving funds
        attacker.setAttackerParams{
            value: 0
        }();

        // Ensure contract c has some Ether to pay out
        vm.deal(address(c), 10 ether);

        // Now call getFirstWithdrawalBonus on c targeting our attacker. This will add bonus (100) then call withdrawReward
        // The attacker is designed to reenter withdrawReward during the external call. For the correct contract this is
        // prevented by the nonReentrant guard so after getFirstWithdrawalBonus completes, rewardsForA[attacker] must be 0.
        // For the mutant that zeroes after the external call and lacks proper guard ordering, reentrancy can observe
        // a nonzero rewardsForA during reentry and can break the invariant.

        // call getFirstWithdrawalBonus(attacker)
        vm.prank(address(this));
        // Use low-level call to catch revert if any; we only need final state
        try c.getFirstWithdrawalBonus(address(attacker)) {
            // no-op
        } catch {
            // ignore
        }

        // Exactly one assertion: after the call completes, rewardsForA[attacker] must be zero as observed via attempting
        // to withdraw again — a successful withdraw of zero value should not transfer Ether; we observe c.balance
        // Save balance before second withdraw attempt
        uint256 balBefore = address(c).balance;

        // Try to withdraw again to see if any funds remain for attacker. If rewardsForA was zero, no funds are sent and
        // c.balance remains unchanged. If mutant left nonzero, withdrawing will transfer >0 and reduce c.balance.
        bool ok;
        try c.withdrawReward(address(attacker)) {
            ok = true;
        } catch {
            ok = false;
        }

        uint256 balAfter = address(c).balance;

        // The universal property: reference ensures no funds left for attacker after first call, so second withdraw
        // does not change contract balance. That holds for all inputs. The mutant can be re-entered and leave funds,
        // so for some fuzzed inputs (attacker behavior) the balance will decrease on second withdraw, violating rule.
        assertTrue(balAfter == balBefore);
    }
}

// Minimal attacker that reenters withdrawReward on receiving Ether
contract Attacker {
    address public target;
    bool public reentered;

    constructor(address _target) payable {
        target = _target;
    }

    function setAttackerParams() external payable {
        // placeholder to match set up call
    }

    receive() external payable {
        // on receiving funds, try to re-enter withdrawReward once
        if (!reentered) {
            reentered = true;
            // reenter
            (bool success, ) = target.call(abi.encodeWithSignature("withdrawReward(address)", address(this)));
            // ignore success
            success;
        }
    }
}
